"""Extract closed source patch buffers from the original ARM32 compiler graph.

No mod names, address catalog or initializer text parsing selects a contract.
Native callbacks remain typed symbolic words; never truncate an LP64 address.
"""
from dataclasses import dataclass
import re

from .sr_mod_object import ModObjectError, canonical_type, nodes
from .sr_mod_provenance import direct_function
from .sr_mod_templates import executable_nodes
from .sr_mod_sdk_requests import PublicRequests


@dataclass(frozen=True)
class Constant:
    value: object
    type: str
    address: bool = False


def scalar_size(value):
    value = value.replace('const ', '').replace('volatile ', '').strip()
    aliases = {'char': 1, 'signed char': 1, 'unsigned char': 1, 'bool': 1,
        'short': 2, 'unsigned short': 2, 'int': 4, 'unsigned int': 4,
        'long': 4, 'unsigned long': 4, 'long long': 8, 'unsigned long long': 8,
        'std::uint8_t': 1, 'std::uint16_t': 2, 'std::uint32_t': 4, 'std::uint64_t': 8,
        'std::uintptr_t': 4, 'std::size_t': 4}
    if value not in aliases:
        raise ModObjectError('PATCH_CONSTANT_TYPE_REQUIRED ' + value)
    return aliases[value]


def closed_compiler_bindings(root, *, capture_slots=False):
    rows = list(executable_nodes(root))
    declarations = {row['id']: row for row in rows if row.get('id')}
    parents = {}
    for row in rows:
        for child in row.get('inner', ()):
            parents[id(child)] = row
    functions = {row['id']: row for row in rows if row.get('kind') == 'FunctionDecl'
                 and any(n.get('kind') == 'CompoundStmt' for n in row.get('inner', ()))}
    callers = {identifier: [] for identifier in functions}
    unsafe_bindings, direct_references = set(), set()
    for row in rows:
        children = row.get('inner', ())
        target = None
        if row.get('kind') in ('BinaryOperator', 'CompoundAssignOperator') and row.get('opcode') in (
                '=', '+=', '-=', '*=', '/=', '%=', '<<=', '>>=', '&=', '|=', '^=') and children:
            target = children[0]
        if row.get('kind') == 'UnaryOperator' and row.get('opcode') in ('++', '--', '&') and children:
            # Function and immutable buffer addresses remain supported. This
            # rejects address exposure only when an evaluated binding is used.
            target = children[0]
        if row.get('kind') == 'CXXConstCastExpr':
            target = row
        if target is not None:
            unsafe_bindings.update(n.get('referencedDecl', {}).get('id') for n in nodes(target)
                                   if n.get('kind') == 'DeclRefExpr')
        if row.get('kind') != 'CallExpr' or not row.get('inner'): continue
        reference = direct_function(row['inner'][0])
        if reference and reference.get('id') in callers:
            callers[reference['id']].append(row)
            direct_references.update(id(n) for n in nodes(row['inner'][0])
                                     if n.get('kind') == 'DeclRefExpr' and n.get('referencedDecl', {}).get('id') == reference['id'])
    escaped_functions = {n['referencedDecl']['id'] for n in rows if n.get('kind') == 'DeclRefExpr'
                         and n.get('referencedDecl', {}).get('id') in functions and id(n) not in direct_references}
    parameter_owners = {p['id']: identifier for identifier, function in functions.items()
                        for p in function.get('inner', ()) if p.get('kind') == 'ParmVarDecl'}

    def ancestors(row):
        while id(row) in parents:
            row = parents[id(row)]
            yield row

    def evaluate(row, environment, active=frozenset()):
        kind, children = row.get('kind'), row.get('inner', ())
        spelling = canonical_type(row)
        if kind in ('ImplicitCastExpr', 'ParenExpr', 'CXXStaticCastExpr', 'CXXReinterpretCastExpr', 'CStyleCastExpr',
                    'ExprWithCleanups', 'MaterializeTemporaryExpr', 'CXXStdInitializerListExpr') and len(children) == 1:
            value = evaluate(children[0], environment, active)
            if '*' in spelling:
                if capture_slots and type(value.value) is int and value.value == 0:
                    return Constant(0, spelling)
                if not value.address and not isinstance(value.value, (list, str)) and not (
                        isinstance(value.value, dict) and 'callback' in value.value):
                    raise ModObjectError('PATCH_BUFFER_STORAGE_ADDRESS_REQUIRED')
                return value
            if isinstance(value.value, list):
                return value
            if type(value.value) is int and 'CastExpr' in kind:
                width = scalar_size(spelling)
                target = spelling.replace('const ', '').replace('volatile ', '').strip()
                number = value.value % (1 << (width * 8))
                if target == 'bool': number = int(value.value != 0)
                elif target != 'char' and not target.startswith(('unsigned ', 'std::uint', 'std::size_t', 'std::uintptr_t')) and number >= 1 << (width * 8 - 1):
                    number -= 1 << (width * 8)
                return Constant(number, spelling)
            return Constant(value.value, spelling or value.type)
        if kind == 'StringLiteral' and isinstance(row.get('value'), str):
            return Constant(row['value'], spelling)
        if kind in ('IntegerLiteral', 'CharacterLiteral', 'ConstantExpr') and 'value' in row:
            return Constant(int(row['value']), spelling)
        if kind == 'ImplicitValueInitExpr':
            if capture_slots and '*' in spelling:
                return Constant(0, spelling)
            scalar_size(spelling)
            return Constant(0, spelling)
        if capture_slots and kind in ('CXXNullPtrLiteralExpr', 'GNUNullExpr'):
            return Constant(0, spelling)
        if kind == 'DeclRefExpr':
            reference = row.get('referencedDecl', {})
            identifier = reference.get('id')
            if identifier in environment:
                if identifier in unsafe_bindings or parameter_owners.get(identifier) in escaped_functions:
                    raise ModObjectError('IMMUTABLE_CLOSED_PATCH_BINDING_REQUIRED')
                value = environment[identifier]
                if value is None: raise ModObjectError('DYNAMIC_PATCH_ARGUMENT')
                return value
            declaration = declarations.get(identifier, reference)
            if declaration.get('kind') == 'FunctionDecl':
                return Constant(dict(callback=declaration.get('mangledName'),
                    prototype=canonical_type(declaration)), spelling)
            if identifier in active or not declaration.get('inner'):
                raise ModObjectError('CLOSED_PATCH_CONSTANT_REQUIRED')
            if not declaration.get('constexpr') and 'const' not in canonical_type(declaration):
                raise ModObjectError('IMMUTABLE_PATCH_CONSTANT_REQUIRED')
            return evaluate(declaration['inner'][-1], environment, active | {identifier})
        if kind == 'InitListExpr':
            extent = re.search(r'\[(\d+)\]$', spelling)
            if extent and 'array_filler' in row:
                count = int(extent[1])
                fillers = row['array_filler']
                if children or not fillers or not 0 < count <= 65536 or len(fillers) - 1 > count:
                    raise ModObjectError('BOUNDED_PATCH_ARRAY_INITIALIZER_REQUIRED')
                default = evaluate(fillers[0], environment, active)
                values = [evaluate(child, environment, active) for child in fillers[1:]]
                return Constant(values + [default] * (count - len(values)), spelling)
            values = [evaluate(child, environment, active) for child in children]
            if re.search(r'\[\d+\]', spelling): return Constant(values, spelling)
            name = spelling.replace('const ', '').split('::')[-1]
            records = [n for n in rows if n.get('kind') == 'CXXRecordDecl'
                       and n.get('completeDefinition') and n.get('name') == name]
            if len(records) != 1: raise ModObjectError('UNIQUE_PATCH_AGGREGATE_REQUIRED')
            fields = [n for n in records[0].get('inner', ()) if n.get('kind') == 'FieldDecl']
            if len(fields) != len(values): raise ModObjectError('COMPLETE_PATCH_AGGREGATE_REQUIRED')
            return Constant({field['id']: value for field, value in zip(fields, values)}, spelling)
        if kind == 'MemberExpr' and len(children) == 1:
            value = evaluate(children[0], environment, active).value
            member = row.get('referencedMemberDecl')
            if isinstance(value, dict) and member in value: return value[member]
            raise ModObjectError('STATIC_PATCH_MEMBER_REQUIRED')
        if kind == 'ArraySubscriptExpr' and len(children) == 2:
            array = evaluate(children[0], environment, active).value
            index = evaluate(children[1], environment, active).value
            if not isinstance(array, list) or type(index) is not int or not 0 <= index < len(array):
                raise ModObjectError('STATIC_PATCH_INDEX_REQUIRED')
            return array[index]
        if kind == 'UnaryOperator' and len(children) == 1:
            reference = children[0]
            while reference.get('kind') in ('ImplicitCastExpr', 'ParenExpr') and len(reference.get('inner', ())) == 1:
                reference = reference['inner'][0]
            declaration = declarations.get(reference.get('referencedDecl', {}).get('id'), {})
            if capture_slots and row.get('opcode') == '&' and declaration.get('kind') == 'VarDecl' and \
                    '(*' in canonical_type(declaration).replace(' ', ''):
                return Constant(dict(original=declaration.get('mangledName'),
                    prototype=canonical_type(declaration)), spelling, True)
            value = evaluate(children[0], environment, active)
            if row.get('opcode') == '&':
                return Constant(value.value, value.type, True)
            if row.get('opcode') == '-' and type(value.value) is int: return Constant(-value.value, spelling)
        if kind == 'UnaryExprOrTypeTraitExpr' and row.get('name') == 'sizeof':
            value = evaluate(children[0], environment, active) if children else None
            if value and isinstance(value.value, list): return Constant(sum(len(pack(v)) for v in value.value), spelling)
            source_type = row.get('argType', {}).get('desugaredQualType', row.get('argType', {}).get('qualType', ''))
            return Constant(scalar_size(source_type or value.type), spelling)
        raise ModObjectError('UNSUPPORTED_PATCH_CONSTANT ' + str(kind))

    def pack(value):
        if isinstance(value.value, list): return [part for child in value.value for part in pack(child)]
        size = scalar_size(value.type)
        if type(value.value) is int:
            return list((value.value % (1 << (8 * size))).to_bytes(size, 'little'))
        if isinstance(value.value, dict) and 'callback' in value.value and size == 4:
            if not value.value['callback'] or not value.value['prototype']:
                raise ModObjectError('TYPED_PATCH_CALLBACK_REQUIRED')
            return [dict(value.value, byte=index) for index in range(4)]
        raise ModObjectError('PATCH_BYTES_OR_TYPED_CALLBACK_REQUIRED')

    def contexts(row, active=frozenset()):
        owner = next((n for n in ancestors(row) if n.get('id') in functions), None)
        if owner is None: return [{}]
        identifier = owner['id']
        if identifier in active: raise ModObjectError('CYCLIC_PATCH_HELPER')
        parameters = [n for n in owner.get('inner', ()) if n.get('kind') == 'ParmVarDecl']
        environments = []
        if not parameters: environments.append({})
        else:
            for call in callers[identifier]:
                if len(call['inner']) != len(parameters) + 1: raise ModObjectError('COMPLETE_PATCH_CALL_REQUIRED')
                for outer in contexts(call, active | {identifier}):
                    environment = {}
                    for parameter, argument in zip(parameters, call['inner'][1:]):
                        try: environment[parameter['id']] = evaluate(argument, outer)
                        except ModObjectError: environment[parameter['id']] = None
                    environments.append(environment)
            if not environments: environments.append({})
        for loop in reversed([n for n in ancestors(row) if n is not owner and n.get('kind') == 'CXXForRangeStmt']):
            variables = [v for child in loop.get('inner', ()) if child.get('kind') == 'DeclStmt'
                         for v in child.get('inner', ()) if v.get('kind') == 'VarDecl']
            ranges = [v for v in variables if v.get('isImplicit') and '&' in canonical_type(v)
                      and ('[' in canonical_type(v) or canonical_type(v).startswith('std::initializer_list<'))]
            iteration = [v for v in variables if not v.get('isImplicit')]
            if len(ranges) != 1 or len(iteration) != 1: raise ModObjectError('CLOSED_PATCH_RANGE_REQUIRED')
            expanded = []
            for environment in environments:
                values = evaluate(ranges[0]['inner'][-1], environment).value
                if not isinstance(values, list) or len(values) > 256: raise ModObjectError('BOUNDED_PATCH_RANGE_REQUIRED')
                expanded.extend({**environment, iteration[0]['id']: value} for value in values)
            environments = expanded
        return environments

    return dict(rows=rows, declarations=declarations, parents=parents,
                evaluate=evaluate, pack=pack, contexts=contexts)


def extract_patch_buffers(root):
    bindings = closed_compiler_bindings(root)
    rows, declarations, parents = (bindings[name] for name in ('rows', 'declarations', 'parents'))
    evaluate, pack, contexts = (bindings[name] for name in ('evaluate', 'pack', 'contexts'))
    public = PublicRequests(rows, declarations, parents, service='patch_bytes',
        record='mf_byte_patch_v1', fields=['struct_size', 'behavior', 'hook_id',
            'target_library', 'offset', 'expected_bytes', 'replacement_bytes', 'byte_count'], label='PATCH')

    def public_string(row, environment):
        try:
            value = evaluate(row, environment).value
        except ModObjectError as error:
            raise ModObjectError('LITERAL_PUBLIC_PATCH_LIBRARY_REQUIRED') from error
        if not isinstance(value, str):
            raise ModObjectError('LITERAL_PUBLIC_PATCH_LIBRARY_REQUIRED')
        if len(value) < 2 or not value.startswith('"') or not value.endswith('"'):
            raise ModObjectError('PUBLIC_PATCH_LIBRARY_ENCODING_REQUIRED')
        value = value[1:-1]
        if not value or chr(92) in value:
            raise ModObjectError('PUBLIC_PATCH_LIBRARY_ENCODING_REQUIRED')
        return value

    patches = {}
    public.validate_services()
    for row in rows:
        children = row.get('inner', ())
        request = None
        if public.service_call(row):
            request = public.request(row)
            arguments = [request[name] for name in ('offset', 'expected_bytes', 'replacement_bytes', 'byte_count')]
        else:
            if row.get('kind') != 'CXXMemberCallExpr' or not children or children[0].get('name') != 'patch_built_in_bytes': continue
            receiver = children[0].get('inner', ())
            if len(receiver) != 1 or canonical_type(receiver[0]).replace('const ', '').strip(' &*') != 'modframework::Runtime':
                raise ModObjectError('PATCH_SDK_RECEIVER_REQUIRED')
            if len(children) != 8: raise ModObjectError('PATCH_SDK_ARGUMENT_CONTRACT')
            arguments = children[3:7]
        for environment in contexts(row):
            rva = evaluate(arguments[0], environment).value
            before, after = pack(evaluate(arguments[1], environment)), pack(evaluate(arguments[2], environment))
            size = evaluate(arguments[3], environment).value
            if type(rva) is not int or not 0 <= rva < 2**32 or type(size) is not int or not 0 < size <= 65536:
                raise ModObjectError('BOUNDED_PATCH_SOURCE_SPAN_REQUIRED')
            if len(before) < size or len(after) < size or any(type(byte) is not int for byte in before[:size]):
                raise ModObjectError('COMPLETE_PATCH_SOURCE_BUFFERS_REQUIRED expected=%d replacement=%d requested=%d' %
                                     (len(before), len(after), size))
            contract = dict(rva=rva, expected=bytes(before[:size]).hex(), replacement=after[:size])
            if request is not None:
                contract['target_library'] = public_string(request['target_library'], environment)
            key = (contract.get('target_library', ''), rva)
            previous = patches.setdefault(key, contract)
            if previous != contract: raise ModObjectError('AMBIGUOUS_PATCH_SOURCE_REPLACEMENT')
    return [patches[key] for key in sorted(patches)]
